-- Private native historical-account pricing evidence. This is not a Fleet
-- action, an invoice claim, a future provider price guarantee or R1 savings.
CREATE TABLE fleet_billing_price_evidence (
 tenant_id text NOT NULL,id text NOT NULL,source_id text NOT NULL,
 membership_receipt_id text NOT NULL,templates_receipt_id text NOT NULL,commitment_receipt_id text NOT NULL,
 content_hash text NOT NULL CHECK(content_hash~'^[a-f0-9]{64}$'),
 document jsonb NOT NULL CHECK(pg_column_size(document)<=131072),
 writer_role text NOT NULL DEFAULT current_user,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,id),
 FOREIGN KEY(tenant_id,source_id) REFERENCES source_registrations(tenant_id,id),
 FOREIGN KEY(tenant_id,membership_receipt_id) REFERENCES source_receipts(tenant_id,id),
 FOREIGN KEY(tenant_id,templates_receipt_id) REFERENCES source_receipts(tenant_id,id),
 FOREIGN KEY(tenant_id,commitment_receipt_id) REFERENCES source_receipts(tenant_id,id)
);
ALTER TABLE fleet_billing_price_evidence ENABLE ROW LEVEL SECURITY;
ALTER TABLE fleet_billing_price_evidence FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON fleet_billing_price_evidence USING(tenant_id=current_setting('app.tenant_id',true)) WITH CHECK(tenant_id=current_setting('app.tenant_id',true));
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON fleet_billing_price_evidence FOR EACH ROW EXECUTE FUNCTION deny_evidence_mutation();
GRANT SELECT,INSERT ON fleet_billing_price_evidence TO finops_ingester;
GRANT SELECT ON fleet_billing_price_evidence TO finops_api,finops_worker,finops_signer,finops_executor;
-- Row locking must not grant the reader permission to edit registration.
CREATE FUNCTION fleet_billing_source_lock(p_tenant text,p_source text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF p_tenant IS DISTINCT FROM current_setting('app.tenant_id',true) THEN RAISE EXCEPTION 'fleet price tenant mismatch';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_tenant||':dependency-graph',0));
 PERFORM 1 FROM source_registrations WHERE tenant_id=p_tenant AND id=p_source FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'fleet price source missing';END IF;
END $$;
REVOKE ALL ON FUNCTION fleet_billing_source_lock(text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION fleet_billing_source_lock(text,text) TO finops_ingester;
CREATE FUNCTION guard_fleet_billing_price() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$
DECLARE reg source_registrations;m source_receipts;tpl source_receipts;c source_receipts;r source_receipts;rev source_revisions;j jsonb;ref jsonb;rid text;period_start timestamptz;period_end timestamptz;
BEGIN
 IF current_user<>'finops_ingester' OR NEW.tenant_id IS DISTINCT FROM current_setting('app.tenant_id',true) THEN RAISE EXCEPTION 'fleet price requires dedicated ingestion role';END IF;
 IF NOT(NEW.document ?& ARRAY['schema_version','id','kind','binding','source_connection_id','source_config_hash','source_configuration','membership_receipt_id','launch_templates_receipt_id','hardware_receipt_ids','billing_source_refs','commitment_receipt_id','baseline','baseline_days','baseline_scope_basis','billing_lag_seconds','old','candidate','economic_scope_hash','status','reason_codes','observed_at','valid_until','execution_authorized','verified_saving','hard_spend_cap']) OR jsonb_typeof(NEW.document->'binding') IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.document->'baseline') IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.document->'old') IS DISTINCT FROM 'object' OR jsonb_typeof(NEW.document->'candidate') IS DISTINCT FROM 'object' OR NEW.document->'baseline'->>'start' IS NULL OR NEW.document->'baseline'->>'end' IS NULL OR NEW.document->>'observed_at' IS NULL OR NEW.document->>'valid_until' IS NULL THEN RAISE EXCEPTION 'fleet price complete immutable metadata required';END IF;
 PERFORM fleet_billing_source_lock(NEW.tenant_id,NEW.source_id);
 SELECT * INTO reg FROM source_registrations WHERE tenant_id=NEW.tenant_id AND id=NEW.source_id;
 SELECT * INTO m FROM source_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.membership_receipt_id AND source_id=NEW.source_id AND kind='AWS_FLEET_MEMBERSHIP' AND writer_role='finops_ingester';
 SELECT * INTO tpl FROM source_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.templates_receipt_id AND source_id=NEW.source_id AND kind='AWS_FLEET_LAUNCH_TEMPLATES' AND writer_role='finops_ingester';
 SELECT * INTO c FROM source_receipts WHERE tenant_id=NEW.tenant_id AND id=NEW.commitment_receipt_id AND source_id=NEW.source_id AND kind='AWS_COMMITMENT' AND writer_role='finops_ingester';
 IF reg.id IS NULL OR reg.kind<>'AWS_CUR2' OR reg.document->'enabled' IS DISTINCT FROM 'true'::jsonb OR reg.document->>'revoked'='true' OR m.id IS NULL OR tpl.id IS NULL OR c.id IS NULL OR tpl.document->>'membership_receipt_id' IS DISTINCT FROM m.id OR m.document->'binding' IS DISTINCT FROM NEW.document->'binding' OR tpl.document->'binding' IS DISTINCT FROM NEW.document->'binding' OR NEW.document->'binding'->>'tenant_id' IS DISTINCT FROM NEW.tenant_id OR NEW.document->'binding'->>'provider' IS DISTINCT FROM 'AWS' OR NEW.document->'binding'->>'region' IS DISTINCT FROM 'eu-west-1' THEN RAISE EXCEPTION 'fleet price source identity invalid';END IF;
 IF NEW.document->>'source_config_hash' IS DISTINCT FROM m.document->>'config_hash' OR NEW.document->>'source_config_hash' IS DISTINCT FROM tpl.document->>'config_hash' OR NEW.document->>'source_config_hash' IS DISTINCT FROM c.document->>'config_hash' THEN RAISE EXCEPTION 'fleet price source configuration mismatch';END IF;
 IF NEW.document->'source_configuration' IS DISTINCT FROM jsonb_build_object('kind',reg.document->'kind','payer_account_id',reg.document->'payer_account_id','usage_account_ids',(SELECT jsonb_agg(value ORDER BY value) FROM jsonb_array_elements(reg.document->'usage_account_ids')),'region',reg.document->'region','export_arn',reg.document->'export_arn','bucket',reg.document->'bucket','bucket_owner',reg.document->'bucket_owner','prefix',reg.document->'prefix','read_role_binding_id',reg.document->'read_role_binding_id') OR NOT coalesce(reg.document->'usage_account_ids' ? (NEW.document->'binding'->>'account_id'),false) OR c.document->'commitment_scope'->>'payer_account_id' IS DISTINCT FROM reg.document->>'payer_account_id' OR NOT coalesce(c.document->'commitment_scope'->'usage_account_ids' ? (NEW.document->'binding'->>'account_id'),false) THEN RAISE EXCEPTION 'fleet price current registration scope changed';END IF;
 IF NOT EXISTS(SELECT 1 FROM source_checkpoints cp WHERE cp.tenant_id=NEW.tenant_id AND cp.source_id=NEW.source_id AND cp.checkpoint_key='status' AND cp.document->>'status'='HEALTHY' AND (cp.document->>'last_sync_at')::timestamptz BETWEEN clock_timestamp()-interval '5 minutes' AND clock_timestamp()+interval '30 seconds') OR (m.document->>'collected_at')::timestamptz NOT BETWEEN clock_timestamp()-interval '5 minutes' AND clock_timestamp()+interval '30 seconds' OR (tpl.document->>'collected_at')::timestamptz NOT BETWEEN clock_timestamp()-interval '5 minutes' AND clock_timestamp()+interval '30 seconds' OR (c.document->'commitment_scope'->>'observed_at')::timestamptz>clock_timestamp()+interval '30 seconds' THEN RAISE EXCEPTION 'fleet price current source or native observations stale';END IF;
 IF m.document->>'collected_at' IS NULL OR tpl.document->>'collected_at' IS NULL OR c.document->'commitment_scope'->>'observed_at' IS NULL OR c.document->'commitment_scope'->'reserved_instance_count' IS NULL OR c.document->'commitment_scope'->'savings_plan_count' IS NULL THEN RAISE EXCEPTION 'fleet price current authority timestamps and scope required';END IF;
 IF NEW.document->>'schema_version' IS DISTINCT FROM '1' OR NEW.document->>'kind' IS DISTINCT FROM 'AWS_FLEET_BILLING_PRICE' OR NEW.document->>'id' IS DISTINCT FROM NEW.id OR NEW.document->>'status' IS DISTINCT FROM 'READY' OR NEW.document->>'source_connection_id' IS DISTINCT FROM NEW.source_id OR NEW.document->>'membership_receipt_id' IS DISTINCT FROM m.id OR NEW.document->>'launch_templates_receipt_id' IS DISTINCT FROM tpl.id OR NEW.document->>'commitment_receipt_id' IS DISTINCT FROM c.id OR NEW.document->'execution_authorized' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'hard_spend_cap' IS DISTINCT FROM 'false'::jsonb OR NEW.document->'verified_saving' IS DISTINCT FROM 'null'::jsonb OR NEW.document->>'baseline_scope_basis' IS DISTINCT FROM 'CURRENT_MEMBERS_NATIVE_BILLING_HISTORY' OR NEW.document->'baseline_days' IS DISTINCT FROM '14'::jsonb OR coalesce(NEW.document->>'economic_scope_hash','')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'fleet price cannot grant execution savings or a price guarantee';END IF;
 IF NEW.document-ARRAY['schema_version','id','kind','binding','source_connection_id','source_config_hash','source_configuration','membership_receipt_id','launch_templates_receipt_id','hardware_receipt_ids','billing_source_refs','commitment_receipt_id','baseline','baseline_days','baseline_scope_basis','billing_lag_seconds','old','candidate','economic_scope_hash','status','reason_codes','observed_at','valid_until','execution_authorized','verified_saving','hard_spend_cap']<>'{}'::jsonb OR jsonb_typeof(NEW.document->'reason_codes') IS DISTINCT FROM 'array' OR NOT(NEW.document->'reason_codes' @> '["CONDITIONAL_HISTORICAL_ACCOUNT_RATE","EXECUTION_AUTHORITY_NOT_GRANTED","NO_PROVIDER_FUTURE_PRICE_GUARANTEE","WORKLOAD_ATTRIBUTION_NOT_PROVEN"]'::jsonb) THEN RAISE EXCEPTION 'fleet price unrelated authority fields';END IF;
 period_start:=(NEW.document->'baseline'->>'start')::timestamptz;period_end:=(NEW.document->'baseline'->>'end')::timestamptz;
 IF period_end-period_start<>interval '14 days' OR period_end<>date_trunc('day',period_end AT TIME ZONE 'UTC') AT TIME ZONE 'UTC' OR period_end>clock_timestamp() OR period_end<clock_timestamp()-interval '48 hours' OR (NEW.document->>'observed_at')::timestamptz<clock_timestamp()-interval '2 minutes' OR (NEW.document->>'observed_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR (NEW.document->>'valid_until')::timestamptz<=clock_timestamp() OR (NEW.document->>'valid_until')::timestamptz>least((NEW.document->>'observed_at')::timestamptz+interval '24 hours',period_end+interval '48 hours') OR (c.document->'commitment_scope'->>'observed_at')::timestamptz<clock_timestamp()-interval '5 minutes' OR c.document->'commitment_scope'->'complete' IS DISTINCT FROM 'true'::jsonb OR c.document->'commitment_scope'->>'scope' IS DISTINCT FROM 'PAYER_ALL_LINKED_ACCOUNTS_ALL_REGIONS' OR c.document->'commitment_scope'->'reserved_instance_count' IS DISTINCT FROM '0'::jsonb OR c.document->'commitment_scope'->'savings_plan_count' IS DISTINCT FROM '0'::jsonb THEN RAISE EXCEPTION 'fleet price historical or current authority stale';END IF;
 IF jsonb_typeof(NEW.document->'hardware_receipt_ids') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'hardware_receipt_ids') NOT BETWEEN 1 AND 512 OR jsonb_typeof(NEW.document->'billing_source_refs') IS DISTINCT FROM 'array' OR jsonb_array_length(NEW.document->'billing_source_refs') NOT BETWEEN 1 AND 3 THEN RAISE EXCEPTION 'fleet price bounded receipt references required';END IF;
 FOR rid IN SELECT jsonb_array_elements_text(NEW.document->'hardware_receipt_ids') LOOP
  SELECT * INTO r FROM source_receipts WHERE tenant_id=NEW.tenant_id AND id=rid AND source_id=NEW.source_id AND kind='AWS_EC2_HARDWARE' AND writer_role='finops_ingester';
  IF r.id IS NULL OR r.document->>'config_hash' IS DISTINCT FROM NEW.document->>'source_config_hash' OR r.document->'binding'->>'account_id' IS DISTINCT FROM NEW.document->'binding'->>'account_id' OR r.document->'binding'->>'region' IS DISTINCT FROM 'eu-west-1' OR (r.document->>'collected_at')::timestamptz NOT BETWEEN clock_timestamp()-interval '5 minutes' AND clock_timestamp()+interval '30 seconds' THEN RAISE EXCEPTION 'fleet price hardware receipt binding invalid';END IF;
 END LOOP;
 FOR ref IN SELECT value FROM jsonb_array_elements(NEW.document->'billing_source_refs') LOOP
  SELECT * INTO r FROM source_receipts WHERE tenant_id=NEW.tenant_id AND id=ref->>'receipt_id' AND source_id=NEW.source_id AND kind='AWS_CUR2' AND writer_role='finops_ingester';
  SELECT * INTO rev FROM source_revisions WHERE tenant_id=NEW.tenant_id AND id=ref->>'revision_id' AND source_id=NEW.source_id AND writer_role='finops_ingester';
  SELECT document INTO j FROM entities WHERE tenant_id=NEW.tenant_id AND kind='ingestion_jobs' AND id=ref->>'ingestion_job_id';
  IF r.id IS NULL OR rev.id IS NULL OR j IS NULL OR r.revision_id IS DISTINCT FROM rev.id OR r.document->>'config_hash' IS DISTINCT FROM NEW.document->>'source_config_hash' OR r.document->>'ingestion_job_id' IS DISTINCT FROM ref->>'ingestion_job_id' OR r.document->>'raw_hash' IS DISTINCT FROM ref->>'raw_hash' OR r.document->>'canonical_hash' IS DISTINCT FROM ref->>'canonical_hash' OR j->>'source_receipt_id' IS DISTINCT FROM r.id OR j->>'source_revision_id' IS DISTINCT FROM rev.id OR j->>'status' IS DISTINCT FROM 'PERSISTED' OR j->>'source_provenance' IS DISTINCT FROM 'AWS_CUR2_AUTHENTICATED' THEN RAISE EXCEPTION 'fleet price native billing receipt binding invalid';END IF;
 END LOOP;
 FOREACH rid IN ARRAY ARRAY['old','candidate'] LOOP
  ref:=NEW.document->rid;
  IF NOT(ref ?& ARRAY['instance_type','rate_dimensions','observed_hourly_rate','usage_hours','observed_current_member_compute_cost','sample_count','latest_usage_end','rate_basis','member_count','member_ids_hash']) OR jsonb_typeof(ref->'sample_count') IS DISTINCT FROM 'number' OR jsonb_typeof(ref->'member_count') IS DISTINCT FROM 'number' OR ref->>'latest_usage_end' IS NULL THEN RAISE EXCEPTION 'fleet price complete native rate metadata required';END IF;
  IF ref-ARRAY['instance_type','rate_dimensions','observed_hourly_rate','usage_hours','observed_current_member_compute_cost','sample_count','latest_usage_end','rate_basis','member_count','member_ids_hash']<>'{}'::jsonb OR (ref->'rate_dimensions')-ARRAY['account_id','region','currency','instance_type','operating_system','tenancy','license_model','preinstalled_software','sku','operation','usage_type','unit','cost_basis']<>'{}'::jsonb OR coalesce(ref->'rate_dimensions'->>'currency','')!~'^[A-Z]{3}$' OR coalesce(ref->>'usage_hours','')!~'^[0-9]+(\.[0-9]+)?$' OR (ref->>'usage_hours')::numeric<=0 OR coalesce(ref->>'observed_current_member_compute_cost','')!~'^[0-9]+(\.[0-9]+)?$' OR (ref->>'observed_current_member_compute_cost')::numeric<=0 OR (ref->>'sample_count')::int<1 OR (ref->>'member_count')::int<1 OR coalesce(ref->>'member_ids_hash','')!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'fleet price bounded exact historical rate fields required';END IF;
  IF ref->>'rate_basis' IS DISTINCT FROM 'HISTORICAL_ACCOUNT_RATE_ESTIMATE' OR coalesce(ref->>'observed_hourly_rate','')!~'^[0-9]+(\.[0-9]+)?$' OR (ref->>'observed_hourly_rate')::numeric<=0 OR ref->'rate_dimensions'->>'account_id' IS DISTINCT FROM NEW.document->'binding'->>'account_id' OR ref->'rate_dimensions'->>'region' IS DISTINCT FROM 'eu-west-1' OR ref->'rate_dimensions'->>'operating_system' IS DISTINCT FROM 'Linux' OR ref->'rate_dimensions'->>'tenancy' IS DISTINCT FROM 'Shared' OR ref->'rate_dimensions'->>'license_model' IS DISTINCT FROM 'No License required' OR ref->'rate_dimensions'->>'preinstalled_software' IS DISTINCT FROM 'NA' OR ref->'rate_dimensions'->>'operation' IS DISTINCT FROM 'RunInstances' OR ref->'rate_dimensions'->>'unit' IS DISTINCT FROM 'Hrs' OR coalesce(ref->'rate_dimensions'->>'sku','')='' OR ref->'rate_dimensions'->>'cost_basis' NOT IN('UNBLENDED','NET_UNBLENDED') THEN RAISE EXCEPTION 'fleet price exact native dimensions required';END IF;
 END LOOP;
 IF NEW.document->'old'->'rate_dimensions'->>'currency' IS DISTINCT FROM NEW.document->'candidate'->'rate_dimensions'->>'currency' THEN RAISE EXCEPTION 'fleet price cannot blend currencies';END IF;
 NEW.writer_role:='finops_ingester';NEW.created_at:=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER writer BEFORE INSERT ON fleet_billing_price_evidence FOR EACH ROW EXECUTE FUNCTION guard_fleet_billing_price();
REVOKE ALL ON FUNCTION guard_fleet_billing_price() FROM PUBLIC;
